 38→func (a *openCodeAgent) IsTransientError(out Output, err error) bool {
 39→	if err == nil {
 40→		return false
 41→	}
 42→	combined := out.Stdout + out.Stderr
 43→	transientPatterns := []string{
 44→		"overloaded",
 45→		"rate limit",
 46→		"529",
 47→		"503",
 48→		"ECONNRESET",
 49→		"ETIMEDOUT",
 50→	}
 51→	for _, p := range transientPatterns {
 52→		if strings.Contains(combined, p) {
 53→			return true
 54→		}
 55→	}
 56→	return false
 57→}
