 59→func (a *openCodeAgent) Bootstrap() error {
 60→	// opencode has first-run DB migration + node_modules resolution that
 61→	// races with parallel test execution (upstream issue #6935).
 62→	// Run a trivial prompt to force full initialization before tests.
 63→	for i := range 3 {
 64→		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
 65→		cmd := exec.CommandContext(ctx, a.Binary(), "run", "--model", a.model, "say hi")
 66→		cmd.Env = os.Environ()
 67→		out, err := cmd.CombinedOutput()
 68→		cancel()
 69→		if err == nil {
 70→			return nil
 71→		}
 72→		if i < 2 {
 73→			fmt.Fprintf(os.Stderr, "opencode warmup attempt %d failed: %s\n%s\n", i+1, err, out)
 74→			time.Sleep(5 * time.Second)
 75→		}
 76→	}
 77→	// Non-fatal: warmup failure shouldn't block tests entirely.
 78→	fmt.Fprintln(os.Stderr, "opencode warmup failed after 3 attempts, proceeding anyway")
 79→	return nil
 80→}
