 82→func (a *openCodeAgent) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 83→	cfg := &runConfig{}
 84→	for _, o := range opts {
 85→		o(cfg)
 86→	}
 87→
 88→	model := a.model
 89→	if cfg.Model != "" {
 90→		model = cfg.Model
 91→	}
 92→
 93→	args := []string{"run"}
 94→	if model != "" {
 95→		args = append(args, "--model", model)
 96→	}
 97→	args = append(args, prompt)
 98→
 99→	timeout := a.timeout
100→	if envTimeout := os.Getenv("E2E_TIMEOUT"); envTimeout != "" {
101→		if parsed, err := time.ParseDuration(envTimeout); err == nil {
102→			timeout = parsed
103→		}
104→	}
105→
106→	ctx, cancel := context.WithTimeout(ctx, timeout)
107→	defer cancel()
108→
109→	cmd := exec.CommandContext(ctx, a.Binary(), args...)
110→	cmd.Dir = dir
111→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
112→
113→	var stdout, stderr strings.Builder
114→	cmd.Stdout = &stdout
115→	cmd.Stderr = &stderr
116→
117→	err := cmd.Run()
118→	out := Output{
119→		Command: a.Binary() + " " + strings.Join(args, " "),
120→		Stdout:  stdout.String(),
121→		Stderr:  stderr.String(),
122→	}
123→
124→	if err != nil {
125→		var exitErr *exec.ExitError
126→		if errors.As(err, &exitErr) {
127→			out.ExitCode = exitErr.ExitCode()
128→		} else {
129→			out.ExitCode = -1
130→		}
131→		return out, err
132→	}
133→
134→	return out, nil
135→}
