137→func (a *openCodeAgent) StartSession(ctx context.Context, dir string) (Session, error) {
138→	// opencode's TUI occasionally fails to render on CI (empty pane).
139→	// Retry once if the first attempt produces no output at all.
140→	var s *TmuxSession
141→	var lastErr error
142→	for attempt := range 2 {
143→		name := fmt.Sprintf("opencode-test-%d", time.Now().UnixNano())
144→		var err error
145→		s, err = NewTmuxSession(name, dir, nil, "env", "ENTIRE_TEST_TTY=0", a.Binary(), "--model", a.model)
146→		if err != nil {
147→			return nil, err
148→		}
149→
150→		// Wait for TUI to be ready (input area with placeholder text).
151→		if _, err := s.WaitFor(`Ask anything`, 15*time.Second); err != nil {
152→			content := s.Capture()
153→			_ = s.Close()
154→			if strings.TrimSpace(content) == "" && attempt == 0 {
155→				lastErr = err
156→				continue
157→			}
158→			return s, fmt.Errorf("waiting for startup: %w", err)
159→		}
160→		s.stableAtSend = ""
161→		return s, nil
162→	}
163→	return nil, fmt.Errorf("opencode TUI failed to start after retry: %w", lastErr)
164→}
