69→// AcquireSlot blocks until a test slot is available for the agent or the
70→// context is cancelled. Returns a non-nil error if the context expires
71→// before a slot opens.
72→func AcquireSlot(ctx context.Context, a Agent) error {
73→	g, ok := gates[a.Name()]
74→	if !ok {
75→		return nil
76→	}
77→	select {
78→	case g <- struct{}{}:
79→		return nil
80→	case <-ctx.Done():
81→		return ctx.Err()
82→	}
83→}
