  1→package testutil
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"errors"
  7→	"fmt"
  8→	"os"
  9→	"os/exec"
 10→	"path/filepath"
 11→	"strings"
 12→	"testing"
 13→	"time"
 14→
 15→	"github.com/entireio/cli/e2e/agents"
 16→	"github.com/entireio/cli/e2e/entire"
 17→)
 18→
 19→// RepoState holds the working state for a single test's cloned repository.
 20→type RepoState struct {
 21→	Agent            agents.Agent
 22→	Dir              string
 23→	ArtifactDir      string
 24→	HeadBefore       string
 25→	CheckpointBefore string
 26→	ConsoleLog       *os.File
 27→}
 28→
 29→// SetupRepo creates a fresh git repository in a temporary directory, seeds it
 30→// with an initial commit, and runs `entire enable` for the given agent.
 31→// Artifact capture is registered as a cleanup function.
 32→//
 33→// When E2E_KEEP_REPOS is set, the temporary directory is not cleaned up
 34→// so it can be inspected after the test. A symlink in the artifact dir
 35→// points to the preserved repo.
 36→func SetupRepo(t *testing.T, agent agents.Agent) *RepoState {
 37→	t.Helper()
 38→
 39→	keepRepos := os.Getenv("E2E_KEEP_REPOS") != ""
 40→
 41→	// Always use os.MkdirTemp instead of t.TempDir(). Go's t.TempDir()
 42→	// creates nested subdirectories (TestName.../001/) whose structure
 43→	// confuses some agents' (e.g. opencode) working-directory resolution.
 44→	dir, err := os.MkdirTemp("", "e2e-repo-*")
 45→	if err != nil {
 46→		t.Fatalf("create temp dir: %v", err)
 47→	}
 48→	if keepRepos {
 49→		t.Logf("E2E_KEEP_REPOS: repo will be preserved at %s", dir)
 50→	} else {
 51→		t.Cleanup(func() { os.RemoveAll(dir) })
 52→	}
 53→
 54→	// Resolve symlinks (macOS: /var -> /private/var) so paths match
 55→	// what agent CLIs see when they resolve their own CWD.
 56→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
 57→		dir = resolved
 58→	}
 59→
 60→	Git(t, dir, "init")
 61→	Git(t, dir, "config", "user.name", "E2E Test")
 62→	Git(t, dir, "config", "user.email", "e2e@test.local")
 63→	Git(t, dir, "commit", "--allow-empty", "-m", "initial commit")
 64→
 65→	entire.Enable(t, dir, agent.EntireAgent(), "")
 66→	PatchSettings(t, dir, map[string]any{"log_level": "debug"})
 67→
 68→	// OpenCode's non-interactive mode auto-rejects external_directory permission
 69→	// since there's no user to prompt. Write a config to allow it.
 70→	if agent.Name() == "opencode" {
 71→		cfg := `{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}}`
 72→		if key := os.Getenv("ANTHROPIC_API_KEY"); key != "" {
 73→			cfg = fmt.Sprintf(`{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}, "provider": {"anthropic": {"options": {"apiKey": %q}}}}`, key)
 74→		}
 75→		if err := os.WriteFile(filepath.Join(dir, "opencode.json"), []byte(cfg+"\n"), 0o644); err != nil {
 76→			t.Fatalf("write opencode.json: %v", err)
 77→		}
 78→	}
 79→
 80→	// Create artifact dir eagerly so console.log is written to disk
 81→	// incrementally. Even if the test is killed by a global timeout,
 82→	// partial output survives.
 83→	artDir := artifactDir(t)
 84→	consoleLog, err := os.Create(filepath.Join(artDir, "console.log"))
 85→	if err != nil {
 86→		t.Fatalf("create console.log: %v", err)
 87→	}
 88→
 89→	state := &RepoState{
 90→		Agent:            agent,
 91→		Dir:              dir,
 92→		ArtifactDir:      artDir,
 93→		HeadBefore:       GitOutput(t, dir, "rev-parse", "HEAD"),
 94→		CheckpointBefore: GitOutput(t, dir, "rev-parse", "entire/checkpoints/v1"),
 95→		ConsoleLog:       consoleLog,
 96→	}
 97→
 98→	t.Cleanup(func() {
 99→		_ = consoleLog.Close()
100→		CaptureArtifacts(t, state)
101→	})
102→
103→	return state
104→}
105→
106→// ForEachAgent runs fn as a parallel subtest for every registered agent.
107→// It handles repo setup, concurrency gating, context timeout, and cleanup.
108→// The timeout is scaled by each agent's TimeoutMultiplier.
109→func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
110→	t.Helper()
111→	t.Parallel()
112→	for _, agent := range agents.All() {
113→		t.Run(agent.Name(), func(t *testing.T) {
114→			s := SetupRepo(t, agent)
115→
116→			// Use the global test deadline for slot wait so we don't
117→			// skip prematurely — only bail if the whole binary is dying.
118→			slotCtx := context.Background()
119→			if deadline, ok := t.Deadline(); ok {
120→				var cancel context.CancelFunc
121→				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
122→				defer cancel()
123→			}
124→			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
125→				t.Fatalf("timed out waiting for agent slot: %v", err)
126→			}
127→			defer agents.ReleaseSlot(agent)
128→
129→			// Per-test timeout starts after slot is acquired, scaled
130→			// by the agent's multiplier (e.g. 2.5× for gemini).
131→			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
132→			ctx, cancel := context.WithTimeout(context.Background(), scaled)
133→			defer cancel()
134→			fn(t, s, ctx)
135→		})
136→	}
137→}
138→
139→// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
140→// and returns the result. If the agent reports a transient API error, the
141→// prompt is retried once after a short delay. The caller should still check err.
142→func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
143→	t.Helper()
144→	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
145→	s.logPromptResult(out)
146→
147→	if err != nil && s.Agent.IsTransientError(out, err) {
148→		t.Logf("transient API error detected, retrying in 5s: %v", err)
149→		s.ConsoleLog.WriteString("> [retry] transient error, waiting 5s...\n")
150→		select {
151→		case <-time.After(5 * time.Second):
152→		case <-ctx.Done():
153→			return out, err
154→		}
155→		out, err = s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
156→		s.logPromptResult(out)
157→	}
158→
159→	return out, err
160→}
161→
162→func (s *RepoState) logPromptResult(out agents.Output) {
163→	s.ConsoleLog.WriteString("> " + out.Command + "\n")
164→	s.ConsoleLog.WriteString("stdout:\n" + out.Stdout + "\n")
165→	s.ConsoleLog.WriteString("stderr:\n" + out.Stderr + "\n")
166→}
167→
168→// Git runs a git command in the repo and logs it to ConsoleLog.
169→func (s *RepoState) Git(t *testing.T, args ...string) {
170→	t.Helper()
171→	s.ConsoleLog.WriteString("> git " + strings.Join(args, " ") + "\n")
172→	Git(t, s.Dir, args...)
173→}
174→
175→// Send sends input to an interactive session and logs it to ConsoleLog.
176→// Fails the test on error.
177→func (s *RepoState) Send(t *testing.T, session agents.Session, input string) {
178→	t.Helper()
179→	s.ConsoleLog.WriteString("> send: " + input + "\n")
180→	if err := session.Send(input); err != nil {
181→		t.Fatalf("send failed: %v", err)
182→	}
183→}
184→
185→// PatchSettings merges extra keys into .entire/settings.json.
186→func PatchSettings(t *testing.T, dir string, extra map[string]any) {
187→	t.Helper()
188→	path := filepath.Join(dir, ".entire", "settings.json")
189→	data, err := os.ReadFile(path)
190→	if err != nil {
191→		t.Fatalf("read settings: %v", err)
192→	}
193→	var settings map[string]any
194→	if err := json.Unmarshal(data, &settings); err != nil {
195→		t.Fatalf("parse settings: %v", err)
196→	}
197→	for k, v := range extra {
198→		settings[k] = v
199→	}
200→	out, err := json.MarshalIndent(settings, "", "  ")
201→	if err != nil {
202→		t.Fatalf("marshal settings: %v", err)
203→	}
204→	if err := os.WriteFile(path, out, 0o644); err != nil {
205→		t.Fatalf("write settings: %v", err)
206→	}
207→}
208→
209→// Git runs a git command in the given directory and fails the test if it
210→// returns a non-zero exit code.
211→func Git(t *testing.T, dir string, args ...string) {
212→	t.Helper()
213→
