261→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
262→// checkpoint branch. It parses the two-level directory structure
263→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
264→func CheckpointIDs(t *testing.T, dir string) []string {
265→	t.Helper()
266→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
267→	if out == "" {
268→		return nil
269→	}
270→	seen := map[string]bool{}
271→	var ids []string
272→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
273→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
274→		parts := strings.Split(line, "/")
275→		if len(parts) == 3 && parts[2] == "metadata.json" {
276→			id := parts[0] + parts[1]
277→			if !seen[id] {
278→				seen[id] = true
279→				ids = append(ids, id)
280→			}
281→		}
282→	}
283→	return ids
284→}
