322→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
323→// branch for the given checkpoint ID and session index, then returns it.
324→// This handles the race where the checkpoint branch advances before session
325→// metadata is fully committed.
326→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
327→	t.Helper()
328→
329→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
330→	blob := "entire/checkpoints/v1:" + path
331→
332→	deadline := time.Now().Add(timeout)
333→	for time.Now().Before(deadline) {
334→		raw := gitOutputSafe(dir, "show", blob)
335→		if raw != "" {
336→			var meta SessionMetadata
337→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
338→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
339→			}
340→			return meta
341→		}
342→		time.Sleep(500 * time.Millisecond)
343→	}
344→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
345→	return SessionMetadata{}
346→}
