 93→func (c *Claude) Bootstrap() error {
 94→	// On CI, write a config file so Claude Code uses the API key from the
 95→	// environment instead of trying OAuth/Keychain.
 96→	if os.Getenv("CI") == "" {
 97→		return nil
 98→	}
 99→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
100→	if apiKey == "" {
101→		return nil
