116→func (c *Claude) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
117→	cfg := &runConfig{Model: "haiku"}
118→	for _, o := range opts {
119→		o(cfg)
120→	}
121→
122→	env := append(cleanEnv(),
123→		"ACCESSIBLE=1",
124→		"ENTIRE_TEST_TTY=0",
125→
126→		// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
127→		// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
128→		// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
129→		// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
130→		// itself, clone its plugins, etc.
131→		"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
132→	)
133→
134→	// On CI (no macOS Keychain), use an isolated config dir so Claude Code
135→	// picks up ANTHROPIC_API_KEY from the environment instead of trying OAuth.
136→	// Locally, we skip CLAUDE_CONFIG_DIR so the Keychain-based auth works.
137→	if os.Getenv("CI") != "" {
138→		configDir, err := isolatedConfigDir()
139→		if err != nil {
140→			return Output{}, fmt.Errorf("create isolated config dir: %w", err)
141→		}
142→		defer func() { _ = os.RemoveAll(configDir) }()
143→		env = append(env, "CLAUDE_CONFIG_DIR="+configDir)
144→	}
145→
146→	args := []string{"-p", prompt, "--model", cfg.Model, "--dangerously-skip-permissions"}
147→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--dangerously-skip-permissions"}
148→	cmd := exec.CommandContext(ctx, c.Binary(), args...)
149→	cmd.Dir = dir
150→	cmd.Stdin = nil
151→	cmd.Env = env
152→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
153→	cmd.Cancel = func() error {
154→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
155→	}
156→	cmd.WaitDelay = 5 * time.Second
157→
158→	var stdout, stderr strings.Builder
159→	cmd.Stdout = &stdout
160→	cmd.Stderr = &stderr
161→
162→	err := cmd.Run()
163→	exitCode := 0
164→	exitErr := &exec.ExitError{}
165→	if errors.As(err, &exitErr) {
166→		exitCode = exitErr.ExitCode()
167→	}
168→
169→	return Output{
170→		Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
171→		Stdout:   stdout.String(),
172→		Stderr:   stderr.String(),
173→		ExitCode: exitCode,
174→	}, err
175→}
