177→func (c *Claude) StartSession(ctx context.Context, dir string) (Session, error) {
178→	name := fmt.Sprintf("claude-test-%d", time.Now().UnixNano())
179→
180→	envArgs := []string{
181→		"ACCESSIBLE=1",
182→		"ENTIRE_TEST_TTY=0",
183→
184→		// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
185→		// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
186→		// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
187→		// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
188→		// itself, clone its plugins, etc.
189→		"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
190→	}
191→
192→	// On CI (no macOS Keychain), use an isolated config dir so Claude Code
193→	// picks up ANTHROPIC_API_KEY from the environment instead of trying OAuth.
194→	// Locally, we skip CLAUDE_CONFIG_DIR so the Keychain-based auth works.
195→	if os.Getenv("CI") != "" {
196→		configDir, err := isolatedConfigDir()
197→		if err == nil {
198→			envArgs = append(envArgs, "CLAUDE_CONFIG_DIR="+configDir)
199→		}
200→	}
201→
202→	args := append([]string{"env"}, envArgs...)
203→	args = append(args, c.Binary(), "--dangerously-skip-permissions")
204→	s, err := NewTmuxSession(name, dir, []string{"CLAUDECODE"}, args[0], args[1:]...)
205→	if err != nil {
206→		return nil, err
207→	}
208→
209→	// Dismiss startup dialogs until we reach the input prompt.
210→	for range 5 {
211→		content, err := s.WaitFor(`❯`, 15*time.Second)
212→		if err != nil {
213→			_ = s.Close()
214→			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
215→		}
216→		if !strings.Contains(content, "Enter to confirm") {
217→			break
218→		}
219→		// The bypass permissions dialog defaults to "No, exit" —
220→		// arrow down to "Yes, I accept" before confirming.
221→		if strings.Contains(content, "Yes, I accept") {
222→			_ = s.SendKeys("Down")
223→			time.Sleep(200 * time.Millisecond)
224→		}
225→		_ = s.SendKeys("Enter")
226→		time.Sleep(500 * time.Millisecond)
227→	}
228→	s.stableAtSend = ""
229→
230→	return s, nil
231→}
